CREATE TABLE IF NOT EXISTS admin_users (slot INTEGER PRIMARY KEY CHECK(slot=1),user_id TEXT UNIQUE NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS account_access (user_id TEXT PRIMARY KEY REFERENCES users(id),disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS parent_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id),approval_enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS admin_audit (id TEXT PRIMARY KEY,admin_id TEXT NOT NULL,target_id TEXT NOT NULL,action TEXT NOT NULL,created_at INTEGER NOT NULL);
